// v9.1.9 : coréen complété (Paramètres, fiches d'objet, ensembles, donjons, fenêtres, messages, données du jeu).
// Fusionné dans ./ko.js (EXACT_919 ajouté au dictionnaire, PATTERNS_919 placés avant les motifs existants).
// Les textes coupés par des balises (« Vous gagneras <b>+5 fragments</b> à investir… ») sont traduits morceau
// par morceau : chaque morceau est écrit pour se lire dans l'ordre français (aucun ordre des mots imposé).
// Motifs : petit langage P(français, coréen) — « # » nombre, « @ » texte libre, « ~s » lettre facultative
// (pluriel). Dans le coréen : $1 = nombre (virgule → point), %1 = texte traduit (sinon le motif ne s'applique
// pas), &1 = durée (« 4 h 05 min » → « 4시간 05분 »).
import { makeP } from './engine.js';

let lookup = () => null;
export function setKoLookup(fn) { lookup = fn; }

// Nombre affiché par le jeu : « 12 », « 1,5 », « 3,4 K », « 232,3 ai » (unités aa…zz), « -5 », « ~120 ».
export const NUM = '([+\\-−~]?\\d+(?:[,.]\\d+)?(?: (?:K|M|B|T|Qa|Qi|(?!(?:de|du|en|et|la|le|au|ou|un|il|on|si|ne|se|sa|ce)\\b)[a-z]{2}\\b))?)';
export const dur = (s) => String(s).replace(/(\d+) j\b/g, '$1일').replace(/(\d+) h (\d+) min\b/g, '$1시간 $2분').replace(/(\d+) h (\d\d)\b/g, '$1시간 $2분')
  .replace(/(\d+) h\b/g, '$1시간').replace(/(\d+) min\b/g, '$1분').replace(/(\d+) s\b/g, '$1초');
const trOr = (s) => lookup(s) ?? s;

// Dates françaises : « lundi 9 novembre » → « 11월 9일 월요일 », « 3 nov. » → « 11월 3일 ».
const DAYS = { lundi: '월요일', mardi: '화요일', mercredi: '수요일', jeudi: '목요일', vendredi: '금요일', samedi: '토요일', dimanche: '일요일' };
const MONTHS = ['janv', 'févr', 'mars', 'avr', 'mai', 'juin', 'juil', 'août', 'sept', 'oct', 'nov', 'déc'];
export function frDate(s) {
  const m = String(s).trim().match(/^(?:(lundi|mardi|mercredi|jeudi|vendredi|samedi|dimanche) )?(\d{1,2}) ([a-zéû]+)\.?$/i);
  if (!m) return null;
  const mi = MONTHS.findIndex((x) => m[3].toLowerCase().startsWith(x.slice(0, 3)) && (x !== 'juin' || m[3].startsWith('juin')) && (x !== 'juil' || m[3].startsWith('juil')));
  if (mi < 0) return null;
  return `${mi + 1}월 ${Number(m[2])}일${m[1] ? ` ${DAYS[m[1].toLowerCase()]}` : ''}`;
}

export const P = makeP(NUM, () => lookup, dur);

